/**
 * Lab runner: starts the configured servers and keeps them up until SIGINT.
 *
 *   node lab/server.ts --cert lab/certs/server.pem --key lab/certs/server.key \
 *       --ocsp lab/certs/response.der --port 18443
 *
 * Prints one line per server (profile, port, expected findings) so the
 * checkup run can target them. Certificates are generated by
 * lab/make-certs.sh.
 */
import { parseArgs } from 'node:util';
import { startLab, LAB_PROFILES } from './server.ts';

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      cert: { type: 'string' },
      key: { type: 'string' },
      chain: { type: 'string' },
      ocsp: { type: 'string' },
      port: { type: 'string' },
      only: { type: 'string', multiple: true },
      list: { type: 'boolean' },
    },
  });

  if (values.list) {
    for (const p of LAB_PROFILES) {
      console.log(`${p.name.padEnd(12)} ${p.description}`);
    }
    return;
  }

  const cert = values.cert;
  const key = values.key;
  if (!cert || !key) {
    console.error('error: --cert and --key are required (run lab/make-certs.sh first)');
    process.exitCode = 2;
    return;
  }

  const { servers, failures } = await startLab({
    certPath: cert,
    keyPath: key,
    ...(values.chain ? { chainPath: values.chain } : {}),
    ...(values.ocsp ? { ocspResponsePath: values.ocsp } : {}),
    basePort: values.port ? parseInt(values.port, 10) : 18443,
    ...(values.only ? { only: values.only } : {}),
  });

  console.log('lab servers:');
  for (const s of servers) {
    console.log(`  ${String(s.port).padEnd(6)} ${s.profile.name.padEnd(12)} ${s.profile.description}`);
    console.log(`         expected: versions=${s.profile.expected.versions.join(',') || 'none'}` +
      (s.profile.expected.weakSuites ? ' weak-suites' : '') +
      (s.profile.expected.serverPrefers ? ' server-pref' : '') +
      (s.profile.expected.hsts ? ' hsts' : ''));
  }
  if (failures.length) {
    console.log('\nprofiles that could not start:');
    for (const f of failures) console.log(`  ${f.name}: ${f.reason}`);
  }
  console.log('\nCtrl-C to stop.');

  const shutdown = async () => {
    await Promise.all(servers.map((s) => s.close()));
    process.exit(0);
  };
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
